// `key.remoteJidAlt` e a Evolution AFIRMANDO de quem e o LID — nao e inferencia
// nossa. Uma unica mensagem ao vivo resolve a conversa inteira, e por isso o
// resgate se auto-cura: cliente que volta a escrever destrava o proprio passado.
//
// NAO canonicaliza telefone aqui DE PROPOSITO. A regra ja vive em dois lugares que
// precisam concordar (fn_telefone_wa no banco e telefoneWa no shared); uma terceira
// copia num no do n8n seria a mais facil de divergir e a mais dificil de testar.
// A primeira versao tentou com regex e ja nasceu errada: descartou um cliente de
// DDD 35 cujo numero o WhatsApp guarda no formato antigo (553588438564, sem o 9).
// Mandamos o JID cru; o ingestor canonicaliza com a funcao unica.
const estado = $getWorkflowStaticData("global");
estado.lidsResgatados = estado.lidsResgatados || {};

const registros = $input.first().json?.messages?.records ?? [];
const pares = new Map();

for (const r of registros) {
  const lid = r?.key?.remoteJid;
  const alt = r?.key?.remoteJidAlt;
  if (!lid || !alt || !lid.endsWith("@lid")) continue;
  if (!pares.has(lid)) pares.set(lid, String(alt));
}

const novos = [];
for (const [lid, telefone_wa] of pares) {
  if (estado.lidsResgatados[lid]) continue;
  novos.push({ json: { lid, telefone_wa } });
}

return novos;

// Um item por LID: { resgate: {lid, telefone_wa}, data: [mensagens cruas] }.
// O telefone vai JUNTO porque o ingestor nao tem como derivar telefone de um LID —
// ele roda na nuvem e nao alcanca a Evolution, que e local.
const saida = [];

for (let i = 0; i < $input.all().length; i++) {
  const par = $('Extrair pares LID → telefone').all()[i]?.json;
  if (!par) continue;

  const registros = $input.all()[i].json?.messages?.records ?? [];
  if (registros.length === 0) continue;

  saida.push({ json: { resgate: { lid: par.lid, telefone_wa: par.telefone_wa }, data: registros } });
}

return saida;

// So marca DEPOIS do ingestor confirmar. Se o POST falhar, o LID fica de fora do
// estado e a proxima execucao tenta de novo — o resgate se conserta sozinho.
const estado = $getWorkflowStaticData('global');
estado.lidsResgatados = estado.lidsResgatados || {};

let marcados = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (r?.ok !== true || !r?.lid) continue;
  estado.lidsResgatados[r.lid] = { em: new Date().toISOString(), gravadas: r.gravadas ?? 0 };
  marcados++;
}

return [{ json: { lids_resgatados_agora: marcados, total_no_estado: Object.keys(estado.lidsResgatados).length } }];
